import os,json,stat,shutil,subprocess,time
from pathlib import Path
root=Path('/srv/projects/fadego')
releases=root/'releases'
active_sha='2b3554ec6e075e36041e44178f99535e00961b2f'
fallback_sha='a673ea47272cc2f463f5aa9cfbf2b80c70d80d9d'
result={'scope':'FADEGO old immutable releases only','mode':'bounded hygiene','status':'ABORTED','other_projects_touched':False}
def require(cond,msg):
 if not cond:raise RuntimeError(msg)
def service(n):return subprocess.run(['/usr/bin/systemctl','is-active','--quiet',n],timeout=8).returncode==0
def available():s=os.statvfs('/srv/projects');return s.f_bavail*s.f_frsize
try:
 require(os.geteuid()==0 and root.is_dir() and not root.is_symlink(),'FADEGO not physical')
 require(releases.is_dir() and not releases.is_symlink(),'FADEGO releases are not directory')
 current=root/'current'
 require(current.is_symlink() and os.readlink(current)==('releases/'+active_sha),'active release mismatch')
 keep={active_sha,fallback_sha}
 dirs=sorted([p for p in releases.iterdir() if p.is_dir() and not p.is_symlink()])
 require(len(dirs)==9,'release count changed')
 require(all(len(p.name)==40 and all(c in '0123456789abcdef' for c in p.name) for p in dirs),'unexpected release name')
 require({p.name for p in dirs}.issuperset(keep),'current/rollback release absent')
 doomed=[p for p in dirs if p.name not in keep]
 require(len(doomed)==7,'unexpected prune candidates')
 before={n:service(n) for n in ('fadego-staging','nginx','postgresql@16-main','ssh','pink-iptv-backend')}
 require(all(before.values()),'service not healthy before FADEGO cleanup')
 protected=[str(x) for x in doomed]
 for line in Path('/proc/self/mountinfo').read_text().splitlines():
  fields=line.split()
  if len(fields)>4:require(not any(fields[4].startswith(s+'/') or fields[4]==s for s in protected),'mounted filesystem under old release')
 for proc in Path('/proc').iterdir():
  if not proc.name.isdecimal():continue
  try:
   cwd=os.readlink(proc/'cwd')
   require(not any(cwd==s or cwd.startswith(s+'/') for s in protected),'live process cwd in stale release')
   for fd in (proc/'fd').iterdir():
    try:t=os.readlink(fd)
    except OSError:continue
    require(not any(t==s or t.startswith(s+'/') for s in protected),'live process open old release file')
  except (OSError,PermissionError,ProcessLookupError):pass
 for base in (root,Path('/etc/systemd/system'),Path('/etc/nginx/sites-enabled')):
  for curr,subdirs,files in os.walk(base,followlinks=False):
   if base==root:subdirs[:]=[v for v in subdirs if v not in ('releases','.local','.pnpm-store','.cache','archive','node_modules')]
   if len(Path(curr).parts)-len(base.parts)>4:subdirs[:]=[]
   for name in list(subdirs)+files:
    p=Path(curr)/name
    if p.is_symlink():
     t=str(p.resolve(strict=False))
     require(not any(t==s or t.startswith(s+'/') for s in protected),'symlink targets old release')
 initial=available()
 for path in doomed:shutil.rmtree(path)
 require(len([p for p in releases.iterdir() if p.is_dir() and not p.is_symlink()])==2,'remaining release count wrong')
 require(current.is_symlink() and current.resolve()==releases/active_sha,'active release changed')
 require((releases/fallback_sha).is_dir(),'fallback lost')
 after={n:service(n) for n in before}
 require(after==before,'service status changed after release hygiene')
 result.update(status='PASS',removed_sha_prefixes=[p.name[:12] for p in doomed],removed_release_count=len(doomed),retained_active=active_sha[:12],retained_fallback=fallback_sha[:12],freed_bytes=available()-initial,free_bytes=available(),service_status_unchanged=True)
except Exception as e:result['error']=type(e).__name__+': '+str(e)[:240]
print(json.dumps(result,ensure_ascii=True,sort_keys=True))
